from taf.ul.ettf.ta_matchers.matchers import Any
from collections import namedtuple


Interface = namedtuple('Interface', ['name', 'matcher_name'])
S1AP_PDU = Interface('S1AP', 'S1AP-PDU')
X2AP_PDU = Interface('X2AP', 'X2AP-PDU')


INITIATING_MESSAGE = 'initiatingMessage'
SUCCESSFUL_OUTCOME = 'successfulOutcome'
UNSUCCESSFUL_OUTCOME = 'unsuccessfulOutcome'


def matcher_name(interface_name, name):
    return '{}:{}'.format(interface_name, name[0].title() + name[1:])


def s1ap_message(name, procedure_class_type):
    return ap_message(S1AP_PDU, name, procedure_class_type)


def x2ap_message(name, procedure_class_type):
    return ap_message(X2AP_PDU, name, procedure_class_type)


def ap_message(interface, name, procedure_class_type):
    expected_message_template = Any({
        procedure_class_type: Any({
            'value': Any({
                name: Any()
            })
        })
    })
    return matcher_name(interface.name, name), interface.matcher_name, expected_message_template


def rrc_message(name):
    expected_message_template = Any({
        'c1': Any({
            name: Any()
        })
    })
    return matcher_name('RRC', name), 'message', expected_message_template
